You can simulate a server error by mocking the `requests` call and returning a manually constructed `requests.Response` with a `5xx` status code, such as `500`.

```python
import unittest
from unittest.mock import patch
import requests


def fetch_user(user_id):
    response = requests.get(f"https://example.com/users/{user_id}")
    response.raise_for_status()
    return response.json()


def make_response(status_code, json_data=None, text=""):
    response = requests.Response()
    response.status_code = status_code
    response._content = (
        requests.models.complexjson.dumps(json_data).encode("utf-8")
        if json_data is not None
        else text.encode("utf-8")
    )
    response.headers["Content-Type"] = "application/json"
    response.url = "https://example.com/users/123"
    return response


class TestFetchUser(unittest.TestCase):
    @patch("requests.get")
    def test_server_error(self, mock_get):
        mock_get.return_value = make_response(
            500,
            {"error": "Internal Server Error"}
        )

        with self.assertRaises(requests.HTTPError) as exc:
            fetch_user(123)

        self.assertEqual(exc.exception.response.status_code, 500)
        mock_get.assert_called_once_with("https://example.com/users/123")


if __name__ == "__main__":
    unittest.main()
```

The key part is creating a `requests.Response`, setting `status_code = 500`, and then letting your production code call `raise_for_status()` so the test can verify the error handling path.

Use a thread pool: each worker fetches one URL with `requests`, and the main thread collects the results as they finish.

```python
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed

urls = [
    "https://example.com",
    "https://httpbin.org/get",
    "https://httpbin.org/status/200",
]

def fetch_url(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()

        return {
            "url": url,
            "ok": True,
            "status_code": response.status_code,
            "text": response.text,
        }

    except requests.RequestException as e:
        return {
            "url": url,
            "ok": False,
            "error": str(e),
        }

results = []

with ThreadPoolExecutor(max_workers=10) as executor:
    futures = [executor.submit(fetch_url, url) for url in urls]

    for future in as_completed(futures):
        results.append(future.result())

for result in results:
    if result["ok"]:
        print(f'{result["url"]}: {result["status_code"]}, {len(result["text"])} bytes')
    else:
        print(f'{result["url"]}: ERROR - {result["error"]}')
```

`max_workers` controls how many requests run at the same time. For many URLs, choose a reasonable number like `10`, `20`, or `50` depending on the servers you are calling and your network limits.

Use a streaming response and iterate over decoded lines. SSE events are separated by a blank line; `data:` lines contain the payload.

```python
import httpx


def stream_sse(url: str):
    headers = {
        "Accept": "text/event-stream",
        "Cache-Control": "no-cache",
    }

    with httpx.stream("GET", url, headers=headers, timeout=None) as response:
        response.raise_for_status()

        event = {}

        for line in response.iter_lines():
            # Blank line means the SSE event is complete
            if line == "":
                if event:
                    yield event
                    event = {}
                continue

            # Ignore SSE comments / keep-alives
            if line.startswith(":"):
                continue

            # Parse "field: value"
            if ":" in line:
                field, value = line.split(":", 1)
                value = value.lstrip(" ")
            else:
                field, value = line, ""

            if field == "data":
                event["data"] = event.get("data", "") + value + "\n"
            elif field in {"event", "id", "retry"}:
                event[field] = value


if __name__ == "__main__":
    url = "https://example.com/events"

    for event in stream_sse(url):
        if "data" in event:
            event["data"] = event["data"].rstrip("\n")

        print(event)
```

This keeps the connection open, reads the SSE stream line by line, groups lines into events, and yields each completed event when the server sends a blank line.

Use a mock transport and inject a client into the code you want to test. That way your unit test never performs a real network call.

```python
import httpx


def fetch_user(user_id: int, client: httpx.Client) -> dict:
    response = client.get(f"https://api.example.com/users/{user_id}")
    response.raise_for_status()
    return response.json()


def test_fetch_user():
    def handler(request: httpx.Request) -> httpx.Response:
        assert request.method == "GET"
        assert request.url == "https://api.example.com/users/123"

        return httpx.Response(
            status_code=200,
            json={
                "id": 123,
                "name": "Alice",
            },
        )

    transport = httpx.MockTransport(handler)

    with httpx.Client(transport=transport) as client:
        user = fetch_user(123, client)

    assert user == {
        "id": 123,
        "name": "Alice",
    }
```

The key idea is dependency injection: pass the client into your function, and in tests provide a client backed by `MockTransport` instead of making a real HTTP request.

Use a mock transport that returns a crafted `Response` with a 5xx status code. This lets your test exercise error-handling logic without making a real network call.

```python
import httpx
import pytest


def fetch_user(client: httpx.Client, user_id: int) -> dict:
    response = client.get(f"https://api.example.com/users/{user_id}")
    response.raise_for_status()
    return response.json()


def test_fetch_user_server_error():
    def handler(request: httpx.Request) -> httpx.Response:
        return httpx.Response(
            status_code=500,
            json={"error": "internal server error"},
        )

    transport = httpx.MockTransport(handler)

    with httpx.Client(transport=transport) as client:
        with pytest.raises(httpx.HTTPStatusError) as exc_info:
            fetch_user(client, user_id=123)

    assert exc_info.value.response.status_code == 500
    assert exc_info.value.response.json() == {"error": "internal server error"}
```

The key piece is `MockTransport`: it intercepts the outgoing request and returns the exact response you want to test against.
